#!/bin/bash
# RPD-RECO d2-predict and step0 (rpd_d2s0): the login-node connect, generated from P0's bound connect (6a1bed95) by
# tools/gen_d2s0.py. Login-only at 0 node-h, with no job. It runs only on the director's go for its exact sha256. In
# order, on one login node:
#   1. refuses unless on a login node with the literal root absent;
#   2. the sacct fence (P0's block, flux3's tightened one, byte for byte); then a read-only iris balance read, recorded
#      in this output only and never a gate;
#   3. a fresh clone at the bound sha into the root, HEAD and porcelain checked, and the 14 pinned sha256s;
#   4. the READY config (P0's, unchanged), written from this script and checked against its sha256;
#   5. the in-place inputs, read with O_NOATIME and checked against the committed records (tools/d2s0_checks.py
#      inputs): flux3's extract, custody record and 12 factor products, and P0's run/pins.json and run/p0.json. Then
#      P0's two records are staged byte for byte into the new run directory (tools/d2s0_checks.py stage: O_NOATIME
#      read, sha256 checked, created exclusively, re-read), so the bound CLI sees the pins -> p0 chain;
#   6. a fresh stat (never an open) of the three gen2thin flux files and the 24 dumps against S1 (stat-d2s0.txt);
#   7. the overlap fence (tools/fence_overlap.py, write roots the new root and /dev/shm/limres-rpd-flux1);
#   8. the clone copied to /dev/shm/limres-rpd-flux1/repo, HEAD, porcelain and pins rechecked, the config beside it;
#   9. the runner started detached and handed /dev/shm over, exactly as P0's connect does (P0's handoff: started=1,
#      then handoff.ok; a STOP or signal before that stops the runner's group and removes /dev/shm, checked).
# The runner (rpd_d2s0_runner.sh) runs d2-predict, then step0, in the new run directory. Neither can run dry
# (fd_rpd_reco.py DRY_RUN_SCOPE, :3058-3062), so each runs once, under tools/p0_supervise.py, with its own monotonic
# deadline (7200 s) and a STOP over 8000000000 B peak RSS. No --prediction is passed, so no measured key can be read.
# The fetch reports RUNNING, DONE or STOP. Every Python call has -B. Writes only under the root and
# /dev/shm/limres-rpd-flux1. Nothing is written to CFS. TMPDIR is the root from step 3 on. umask 077. No set -u.
# Launched from a /dev/shm copy of itself ($1), which it deletes.
umask 077
SELF=$1
S=6896e7871421469ce72c6b93188d2d1a55c82ec6
CFG_SHA=3b2afde495d630cc44df730e3e1acf12e0c332953e9fa298fa979f2e2e39b057
FENCE_SHA=33ba39c3ac65e5ca0c6f1c1657fb41a6edbda4af11b94bc3242892774b1c4e21
CHECKS_SHA=d3ff48f98cd797434c213730b9cf6b8bae6904be2b352f499efa1bb29086a506
EXPECTED_SHA=17a13256bac006c87703249989d4504af3144523a4797b95a51ee4a88699b509
SUPERVISE_SHA=6ad0f68fb309a7b83adc0f65ed709e5e2412e650e115075fe41ebbc7a070134f
MAT_PYTHON=/global/homes/j/josephrb/.conda/envs/root_6_28/bin/python3
PY=/global/homes/j/josephrb/.conda/envs/omnifold_py310/bin/python3
made=0
started=0
spid=
launching=0
finish() {
  trap '' TERM INT HUP
  local p=$spid
  [ -z "$p" ] && [ "$launching" -eq 1 ] && p=$!
  if [ -n "$p" ] && [ "$started" -eq 0 ]; then
    kill -TERM -- -"$p" 2>/dev/null; kill -TERM "$p" 2>/dev/null
    for _ in $(seq 1 25); do ps -o stat= -p "$p" 2>/dev/null | grep -qv Z || break; sleep 0.2; done
    kill -KILL -- -"$p" 2>/dev/null; kill -KILL "$p" 2>/dev/null
    wait "$p" 2>/dev/null
    echo "stopped the runner $p before the handoff"
  fi
  if [ "$made" -eq 1 ] && [ "$started" -eq 0 ]; then
    rm -rf -- /dev/shm/limres-rpd-flux1
    if [ -e /dev/shm/limres-rpd-flux1 ]; then echo "STOP: /dev/shm/limres-rpd-flux1 could not be removed"; else echo "removed /dev/shm/limres-rpd-flux1"; fi
  fi
  echo "== rpd-d2s0-connect rc=$1 $(date -u +%FT%TZ)"; rm -f -- "$SELF"; exit "$1"
}
trap 'echo "STOP: the connect got SIGTERM"; finish 8' TERM
trap 'echo "STOP: the connect got SIGINT"; finish 8' INT
trap 'echo "STOP: the connect got SIGHUP"; finish 8' HUP
case "$(hostname)" in login*) ;; *) echo "STOP: not a login node: $(hostname)"; finish 9 ;; esac
[ ! -e /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124 ] || { echo "STOP: /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124 exists"; finish 9; }
echo "node $(hostname) $(date -u +%FT%TZ); connect script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
echo "== 2. the fence (cov2d*, t2a*, rpd* refuse)"
start=$(date -u -d '14 days ago' +%F) || { echo "STOP: start date failed"; finish 3; }
[[ $start =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "STOP: start date malformed: '$start'"; finish 3; }
q=$(sacct -X -n -P -u josephrb -S "$start" -o JobID,JobName,State 2>&1) || { echo "STOP: sacct failed"; printf '%s\n' "$q" | sed 's/^/sacct: /'; finish 3; }
v=$(printf '%s\n' "$q" | awk -F'|' '
  BEGIN { split("BOOT_FAIL CANCELLED COMPLETED DEADLINE FAILED NODE_FAIL OUT_OF_MEMORY PREEMPTED TIMEOUT", t, " ")
          for (i in t) term[t[i]] = 1 }
  /^$/ { next }
  { rows++ }
  NF != 3 || $1 !~ /^[0-9]+([_+].*)?$/ || $2 == "" || $2 ~ /^[[:space:]]|[[:space:]]$/ || $3 !~ /[^[:space:]]/ { print "malformed: " $0; bad = 1; next }
  { split($3, w, " "); if (!(w[1] in term)) print "unended: " $0 }
  tolower($2) ~ /^(cov2d|t2a|rpd)/ { n++; if (!(w[1] in term)) bad = 1 }
  END { print "sacct rows (14 days): " rows + 0 "; cov2d/t2a/rpd rows: " n + 0; exit bad }')
rc=$?
printf '%s\n' "$v" | sed '/^$/d'
[ "$rc" -eq 0 ] || { echo "STOP: a cov2d/t2a/rpd job is unended, or a sacct line is malformed"; finish 3; }
echo "FENCE: clear"
echo "== 2b. iris (read-only balance; recorded here only, not a gate)"
timeout 120 iris < /dev/null 2>&1 | sed 's/^/iris: /'
echo "iris rc=${PIPESTATUS[0]}"
mkdir -m 700 /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124 || finish 9
TMPDIR=/pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124; export TMPDIR  # bash spools heredocs here, inside the root
echo "== 3. fresh clone at $S"
git clone --quiet --filter=blob:none --no-checkout https://github.com/josephbaileyy/MINERvA-OmniFold.git \
  /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/clone || { echo "STOP: clone failed"; finish 5; }
git -C /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/clone fetch --quiet origin "$S" || { echo "STOP: fetch of $S failed"; finish 5; }
git -C /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/clone -c advice.detachedHead=false checkout --quiet "$S" || { echo "STOP: checkout failed"; finish 5; }
head=$(git -C /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/clone rev-parse HEAD)
st=$(git -C /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/clone status --porcelain) || { echo "STOP: git status failed"; finish 5; }
porc=$(printf '%s' "$st" | grep -c '^')
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the clone is not $S clean"; finish 5; }
while read -r want f; do
  got=$(sha256sum "/pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/clone/$f" | cut -d' ' -f1)
  echo "sha256 $got $f"
  [ "$got" = "$want" ] || { echo "STOP: $f is not at its pinned sha256 $want"; finish 5; }
done <<'PINS'
