  /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/production-config.ready.json \
  /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/clone > /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/fence-overlap.txt 2>&1
frc=$?
cat /pscratch/sd/j/josephrb/rpd-reco-d2s0-20261124/fence-overlap.txt; echo "overlap fence rc=$frc"
